    const description = `\u65F6\u5E8F\u7C7B\u578B\uFF1A${orderType}\uFF0C\u65F6\u957F\u4E3B\u5BFC\uFF1A${dominantType}\uFF0C\u9891\u7387\uFF1A${frequencyType}`;
