        lines.push(`- **\u6700\u540E\u51FA\u573A**\uFF1A${(char.lastAppearance * 100).toFixed(1)}%`);
        lines.push(`- **\u51FA\u573A\u6B21\u6570**\uFF1A${char.appearanceCount}`);
        lines.push(`- **\u63D0\u53CA\u6B21\u6570**\uFF1A${char.mentionCount}`);
        lines.push(`- **\u5BF9\u8BDD\u6B21\u6570**\uFF1A${char.dialogueCount ?? 0}`);
        lines.push(`- **\u89C6\u89D2\u6B21\u6570**\uFF1A${char.perspectiveCount ?? 0}`);
